package psx.exporter;
import java.lang.classfile.*;import java.lang.classfile.instruction.*;import java.util.*;
/** A manual button callback may have a constructor-local Action shared by
 * several buttons. Every use of that local must be an exact registration;
 * timer/model registrations, reference escape and opaque triggers stay live. */
final class FmcBackgroundAdmissionButtons {
 private record Creation(Prepare.MethodId method,int at){}
 private record Trigger(Prepare.MethodId method,int at){}
 private final Prepare data;private final Map<Prepare.MethodId,List<Instruction>> ops=new HashMap<>();private final Map<String,List<Creation>> creations=new HashMap<>();private final Set<String> exposed=new HashSet<>();private final List<Trigger> triggers=new ArrayList<>();private final Map<FmcQualification.Member,Boolean> fresh=new HashMap<>();private final Map<Prepare.MethodId,Set<Integer>> entries=new HashMap<>();
 FmcBackgroundAdmissionButtons(Prepare data){this.data=data;for(var e:data.models.entrySet())for(var f:e.getValue().fields())mark(f.fieldType().stringValue());for(var e:data.methods.entrySet()){mark(e.getKey().descriptor());if(e.getValue().code().isEmpty())continue;var list=Prepare.instructions(e.getValue());ops.put(e.getKey(),list);for(int at=0;at<list.size();at++){var op=list.get(at);if(op instanceof NewObjectInstruction n)creations.computeIfAbsent(n.className().asInternalName(),k->new ArrayList<>()).add(new Creation(e.getKey(),at));if(op instanceof ConstantInstruction c&&c.constantValue() instanceof java.lang.constant.ClassDesc type)mark(type.descriptorString());if(op instanceof InvokeInstruction c&&Set.of("doClick","postActionEvent","setModel","setPressed","actionPerformed").contains(c.name().stringValue()))triggers.add(new Trigger(e.getKey(),at));}}}
 private void mark(String descriptor){int start=0;while((start=descriptor.indexOf('L',start))>=0){int end=descriptor.indexOf(';',start);if(end<0)break;exposed.add(descriptor.substring(start+1,end));start=end+1;}}
 boolean quiet(String owner){var model=data.models.get(owner);if(model==null||(model.flags().flagsMask()&ClassFile.ACC_PUBLIC)!=0||exposed.contains(owner))return false;var sites=creations.getOrDefault(owner,List.of());if(sites.isEmpty())return false;for(var creation:sites)if(!registered(owner,creation))return false;return true;}
 private boolean registered(String owner,Creation creation){var list=ops.get(creation.method());int at=creation.at();if(at+1>=list.size()||list.get(at+1).opcode()!=Opcode.DUP)return false;int ctor=-1;for(int p=at+2;p<list.size();p++){var v=list.get(p);if(v instanceof StoreInstruction||v instanceof BranchInstruction||v instanceof ReturnInstruction||v instanceof LookupSwitchInstruction||v instanceof TableSwitchInstruction)return false;if(v instanceof InvokeInstruction c&&c.opcode()==Opcode.INVOKESPECIAL&&c.owner().asInternalName().equals(owner)&&c.name().equalsString("<init>")){ctor=p;break;}}if(ctor<0||ctor+1>=list.size())return false;
  if(list.get(ctor+1) instanceof InvokeInstruction call)return registration(creation.method(),ctor+1,at-1,call);
  if(list.get(ctor+1) instanceof FieldInstruction field&&field.opcode()==Opcode.PUTFIELD&&field.type().equalsString("Ljavax/swing/Action;"))return fieldAction(creation.method(),ctor+1,field);
  if(!(list.get(ctor+1) instanceof StoreInstruction local)||local.typeKind()!=TypeKind.REFERENCE)return false;
  var method=data.methods.get(creation.method());var labels=new HashMap<Label,Integer>();int i=0;for(var e:method.code().orElseThrow()){if(e instanceof LabelTarget l)labels.put(l.label(),i);if(e instanceof Instruction)i++;}var visited=new HashSet<Integer>();var pending=new ArrayDeque<Integer>();pending.add(ctor+2);int uses=0;
  while(!pending.isEmpty()){int p=pending.removeFirst();if(p<0||p>=list.size()||!visited.add(p))continue;var op=list.get(p);if(op instanceof StoreInstruction s&&s.slot()==local.slot())continue;if(op instanceof IncrementInstruction n&&n.slot()==local.slot())return false;
   if(op instanceof LoadInstruction l&&l.slot()==local.slot()){if(l.typeKind()!=TypeKind.REFERENCE||p+1>=list.size()||!(list.get(p+1) instanceof InvokeInstruction call)||!registration(creation.method(),p+1,p-1,call))return false;uses++;}
   for(var h:method.code().orElseThrow().exceptionHandlers()){int begin=labels.get(h.tryStart()),end=labels.get(h.tryEnd());if(p>=begin&&p<end)pending.add(labels.get(h.handler()));}
   if(op instanceof ReturnInstruction||op.opcode()==Opcode.ATHROW)continue;if(op instanceof BranchInstruction b){pending.add(labels.get(b.target()));if(op.opcode()==Opcode.GOTO||op.opcode()==Opcode.GOTO_W)continue;}if(op instanceof LookupSwitchInstruction s){pending.add(labels.get(s.defaultTarget()));s.cases().forEach(c->pending.add(labels.get(c.target())));continue;}if(op instanceof TableSwitchInstruction s){pending.add(labels.get(s.defaultTarget()));s.cases().forEach(c->pending.add(labels.get(c.target())));continue;}pending.add(p+1);
  }return uses>0;
 }
 private boolean fieldAction(Prepare.MethodId creation,int store,FieldInstruction field){var root=FmcQualification.resolveField(data.models,field.owner().asInternalName(),field.name().stringValue(),field.type().stringValue(),new HashSet<>());if(root==null||!creation.name().equals("<init>")||!triggers.isEmpty())return false;int writers=0,uses=0;for(var e:ops.entrySet())for(int at=0;at<e.getValue().size();at++)if(e.getValue().get(at) instanceof FieldInstruction f&&root.equals(FmcQualification.resolveField(data.models,f.owner().asInternalName(),f.name().stringValue(),f.type().stringValue(),new HashSet<>()))){if(f.opcode()==Opcode.PUTFIELD||f.opcode()==Opcode.PUTSTATIC){writers++;if(!e.getKey().equals(creation)||at!=store)return false;}else{var list=e.getValue();if(at+1>=list.size()||!(list.get(at+1) instanceof InvokeInstruction call)||!constructorAction(e.getKey(),at+1,call))return false;uses++;}}return writers==1&&uses>0;}
 private boolean constructorAction(Prepare.MethodId method,int at,InvokeInstruction call){if(!triggers.isEmpty()||call.opcode()!=Opcode.INVOKESPECIAL||!call.name().equalsString("<init>")||!call.type().equalsString("(Ljavax/swing/Action;)V")||!widget(call.owner().asInternalName(),new HashSet<>())||entryPoints(method).contains(at))return false;String owner=call.owner().asInternalName();if(owner.equals("javax/swing/JButton"))return true;var ctor=data.methods.get(new Prepare.MethodId(owner,"<init>","(Ljavax/swing/Action;)V"));if(ctor==null||ctor.code().isEmpty())return false;var list=Prepare.instructions(ctor);if(owner.equals("PButton"))try{if(Identity.hash(data.inputs.get(owner)).equalsIgnoreCase("365D1BB07F03A8B49F0A11524C09F6179691EB60B00AD7BF16D0AF4AE1B20E2B"))return true;}catch(Exception unavailable){return false;}return list.size()==4&&list.get(0) instanceof LoadInstruction a&&a.typeKind()==TypeKind.REFERENCE&&a.slot()==0&&list.get(1) instanceof LoadInstruction v&&v.typeKind()==TypeKind.REFERENCE&&v.slot()==1&&Prepare.call(list.get(2),"javax/swing/JButton","<init>","(Ljavax/swing/Action;)V")&&list.get(3).opcode()==Opcode.RETURN;}
 private boolean registration(Prepare.MethodId method,int invoke,int widgetAt,InvokeInstruction call){if(constructorAction(method,invoke,call))return true;if(call.opcode()!=Opcode.INVOKEVIRTUAL||!(call.name().equalsString("addActionListener")&&call.type().equalsString("(Ljava/awt/event/ActionListener;)V")||call.name().equalsString("setAction")&&call.type().equalsString("(Ljavax/swing/Action;)V"))||!widget(call.owner().asInternalName(),new HashSet<>()))return false;for(String current=call.owner().asInternalName();data.models.containsKey(current);current=data.models.get(current).superclass().map(c->c.asInternalName()).orElse(""))if(data.methods.containsKey(new Prepare.MethodId(current,call.name().stringValue(),call.type().stringValue())))return false;var candidate=field(method,widgetAt,invoke);for(var t:triggers){var c=(InvokeInstruction)ops.get(t.method()).get(t.at());if(c.name().equalsString("actionPerformed"))return false;int receiver=t.at()-1;if(c.typeSymbol().parameterCount()==1){var argument=ops.get(t.method()).get(receiver--);if(!(argument instanceof ConstantInstruction)&&!(argument instanceof LoadInstruction l&&l.typeKind()==TypeKind.INT))return false;}if(c.typeSymbol().parameterCount()>1)return false;var trigger=field(t.method(),receiver,t.at());if(candidate==null||trigger==null||candidate.equals(trigger)||!fresh(candidate)||!fresh(trigger))return false;}return true;}
 private FmcQualification.Member field(Prepare.MethodId method,int at,int invoke){for(int p=at+1;p<=invoke;p++)if(entryPoints(method).contains(p))return null;var list=ops.get(method);if(at<0||at>=list.size()||!(list.get(at) instanceof FieldInstruction f)||f.opcode()!=Opcode.GETFIELD&&f.opcode()!=Opcode.GETSTATIC||!f.type().stringValue().startsWith("L"))return null;return FmcQualification.resolveField(data.models,f.owner().asInternalName(),f.name().stringValue(),f.type().stringValue(),new HashSet<>());}
 private boolean fresh(FmcQualification.Member member){return fresh.computeIfAbsent(member,key->{int stores=0;for(var e:ops.entrySet())for(int at=0;at<e.getValue().size();at++)if(e.getValue().get(at) instanceof FieldInstruction f&&(f.opcode()==Opcode.PUTFIELD||f.opcode()==Opcode.PUTSTATIC)&&key.equals(FmcQualification.resolveField(data.models,f.owner().asInternalName(),f.name().stringValue(),f.type().stringValue(),new HashSet<>()))){stores++;if(!Set.of("<init>","<clinit>").contains(e.getKey().name())||at<3||!(e.getValue().get(at-1) instanceof InvokeInstruction c)||c.opcode()!=Opcode.INVOKESPECIAL||!c.name().equalsString("<init>"))return false;boolean made=false;for(int p=at-2;p>=Math.max(0,at-12);p--){var op=e.getValue().get(p);if(op instanceof StoreInstruction||op instanceof BranchInstruction||op instanceof FieldInstruction f2&&(f2.opcode()==Opcode.PUTFIELD||f2.opcode()==Opcode.PUTSTATIC))break;if(op instanceof NewObjectInstruction n){made=p+1<at&&e.getValue().get(p+1).opcode()==Opcode.DUP&&n.className().asInternalName().equals(c.owner().asInternalName());break;}}if(!made)return false;}return stores>0;});}
 private Set<Integer> entryPoints(Prepare.MethodId method){return entries.computeIfAbsent(method,key->{var labels=new HashMap<Label,Integer>();int at=0;for(var e:data.methods.get(key).code().orElseThrow()){if(e instanceof LabelTarget l)labels.put(l.label(),at);if(e instanceof Instruction)at++;}var points=new HashSet<Integer>();for(var op:ops.get(key)){if(op instanceof BranchInstruction b)points.add(labels.get(b.target()));if(op instanceof LookupSwitchInstruction sw){points.add(labels.get(sw.defaultTarget()));sw.cases().forEach(c->points.add(labels.get(c.target())));}if(op instanceof TableSwitchInstruction sw){points.add(labels.get(sw.defaultTarget()));sw.cases().forEach(c->points.add(labels.get(c.target())));}}for(var h:data.methods.get(key).code().orElseThrow().exceptionHandlers())points.add(labels.get(h.handler()));return Set.copyOf(points);});}
 private boolean widget(String owner,Set<String> seen){if(Set.of("java/awt/Button","java/awt/MenuItem","javax/swing/AbstractButton","javax/swing/JButton","javax/swing/JMenuItem","javax/swing/JToggleButton","javax/swing/JCheckBox","javax/swing/JRadioButton","javax/swing/JCheckBoxMenuItem","javax/swing/JRadioButtonMenuItem").contains(owner))return true;if(!seen.add(owner))return false;var m=data.models.get(owner);return m!=null&&m.superclass().isPresent()&&widget(m.superclass().orElseThrow().asInternalName(),seen);}
}
